var i=`0640-kisra`;var a=`world-0640`;var n=`SD`;var s=`northern-africa`;var r=8;var o=514;var l={en:`Kisra`,ua:`Кісра`};var d={en:`Kisra is a Sudan classic prepared with sorghum flour, instant yeast, white sesame seeds. A measured home-style version, with ingredients assigned to the cooking steps where they are used. Kisra-style sorghum flatbread with a yeast-assisted fermentation; regional naturally soured batter may differ.`,ua:`Кісра, страва кухні країни Судан зі складниками: соргове борошно, інстантні дріжджі, білий кунжут. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування. Коржики у стилі кисри з сорго й дріжджовим бродінням; традиційна природно заквашена основа може відрізнятися.`};var g=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`sorghum-flour`,300,`g`],[`water`,380,`ml`],[`instant-yeast`,2,`g`]]},{en:`Cover the batter loosely and leave in a suitable warm, clean place for about 480 minutes to become bubbly and lightly tangy; do not refrigerate during active fermentation.`,ua:`Нещільно накрийте тісто й залиште приблизно на 480 хвилин у чистому теплому місці до появи бульбашок і легкої кислинки; під час активного бродіння не ставте в холодильник.`,t:[`sourdough-fermentation`],m:480,i:[]},{en:`Spread a very thin layer of tangy sorghum batter onto a lightly oiled hot griddle and cook from one side until the top is set.`,ua:`Розмажте дуже тонкий шар кислуватого тіста з сорго по злегка змащеній гарячій сковороді; готуйте з одного боку до схоплення верху.`,t:[`griddle-cooking`],m:22,i:[[`sunflower-oil`,20,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`white-sesame-seeds`,15,`g`]]}];var u={slug:i,id:a,country:`SD`,region:s,servings:8,minutes:514,title:l,text:d,steps:g};export{n as country,u as default,a as id,o as minutes,s as region,r as servings,i as slug,g as steps,d as text,l as title};